// Summoner's Rift shop built from Riot Data Dragon (src/items.json, generated by scripts/build-all.mjs).
// Stats the engine simulates are kept as numbers (HP, AD, AP, armor, MR, attack speed, move speed, lifesteal,
// ability haste, mana, crit chance/damage, lethality, armor/magic penetration, omnivamp). Passives of the
// most common items are simulated in main.ts (itemOnHit / ITEM_FX below); the rest stay as description text.
import type { ItemDef } from './data';
import raw from './items.json';

interface RawItem {
  id: string; name: string; cost: number; base: number; sell: number; from: string[]; into: string[];
  tags: string[]; stats: Record<string, number>; desc: string; depth: number; stack?: number;
  extra?: { critDmg?: number; leth?: number; apen?: number; mpen?: number; mpenPct?: number; omni?: number };
}
const BOOT_FAMILY = new Set(['1001', '3006', '3009', '3020', '3047', '3111', '3117', '3158']);
export const CONTROL_WARD: ItemDef = { id: 'pink', name: 'Control Ward', cost: 75, desc: 'Hold 1: a visible ward that never expires and reveals hidden wards.', consumable: true, tags: ['Consumable', 'Vision'], from: [], into: [], icon: '2055' };

function convert(r: RawItem): ItemDef | null {
  const s = r.stats;
  const haste = /(\d+) Ability Haste/i.exec(r.desc);
  const it: ItemDef = {
    id: r.id, name: r.name, cost: r.cost, desc: r.desc, tags: r.tags, from: r.from, into: r.into, icon: r.id,
    hp: s.FlatHPPoolMod, ad: s.FlatPhysicalDamageMod, ap: s.FlatMagicDamageMod, armor: s.FlatArmorMod, mr: s.FlatSpellBlockMod,
    as: s.PercentAttackSpeedMod, ms: (s.FlatMovementSpeedMod ?? 0) + (s.PercentMovementSpeedMod ? 340 * s.PercentMovementSpeedMod : 0) || undefined,
    ls: s.PercentLifeStealMod, crit: s.FlatCritChanceMod, ...r.extra, haste: haste ? Number(haste[1]) : undefined, mp: s.FlatMPPoolMod,
    boots: BOOT_FAMILY.has(r.id) || r.tags.includes('Boots') || undefined, depth: r.depth,
  };
  const useful = it.hp || it.ad || it.ap || it.armor || it.mr || it.as || it.ms || it.ls || it.haste || it.mp || it.crit || it.leth || it.apen || it.mpen || it.mpenPct;
  return useful ? it : null;
}
const RAW_POT = (raw as RawItem[]).find((r) => r.id === '2003');
// Health Potion (Data Dragon 2003): 50 gold, stacks to 5, restores 120 Health over 15 seconds (CommunityDragon HealAmount/PotionDuration)
export const HEALTH_POTION: ItemDef = {
  id: '2003', name: RAW_POT?.name ?? 'Health Potion', cost: RAW_POT?.cost ?? 50, desc: RAW_POT?.desc ?? 'Consume: Restores 120 Health over 15 seconds.',
  consumable: true, stack: RAW_POT?.stack ?? 5, tags: ['Consumable'], from: [], into: [], icon: '2003',
};
export const POTION = { heal: 120, dur: 15 };
// Starter items a player buys with the 500 opening gold, as in League: Doran's item + Health Potions.
export const STARTERS = new Set(['1055', '1056', '1054']);
export function starterFor(tags: string[], ranged: boolean): { item: string; pots: number } {
  const t = tags[0];
  if (t === 'Mage' || (t === 'Support' && tags[1] === 'Mage')) return { item: '1056', pots: 2 }; // Doran's Ring 400 + 2
  if (t === 'Tank' || (t === 'Fighter' && !ranged && tags[1] === 'Tank') || t === 'Support') return { item: '1054', pots: 1 }; // Doran's Shield 450 + 1
  return { item: '1055', pots: 1 }; // Doran's Blade 450 + 1
}
// ids above 4 digits are Ornn/Arena variants that duplicate a normal item
export const SHOP_ITEMS: ItemDef[] = (raw as RawItem[])
  .filter((r) => r.id.length <= 4)
  .map(convert)
  .filter((x): x is ItemDef => !!x);
export const ALL_ITEMS: ItemDef[] = [CONTROL_WARD, HEALTH_POTION, ...SHOP_ITEMS];
export const iconUrl = (it: ItemDef) => (it.icon ? `${import.meta.env.BASE_URL}img/item/${it.icon}.png` : '');

// ---- recipes: buying a completed item consumes the components you already own ----
export interface Quote { cost: number; consumed: number[] } // consumed = indices into the inventory
export function quote(id: string, inv: string[], map: Record<string, ItemDef>): Quote {
  const used = new Set<number>();
  const go = (iid: string): number => {
    const it = map[iid];
    if (!it) return 0;
    // an owned copy of this exact component is free
    let total = 0;
    const base = it.from?.length ? 0 : it.cost;
    const comps = it.from ?? [];
    if (!comps.length) return it.cost;
    let sumFull = 0;
    for (const f of comps) {
      sumFull += map[f]?.cost ?? 0;
      const idx = inv.findIndex((x, i) => x === f && !used.has(i));
      if (idx >= 0) used.add(idx);
      else total += go(f);
    }
    return total + (it.cost - sumFull) + base;
  };
  const cost = go(id);
  return { cost, consumed: [...used] };
}

// ---- recommended builds: scored per champion class against what the engine simulates ----
const W: Record<string, Record<string, number>> = {
  Marksman: { ad: 1.4, as: 120, ls: 110, haste: 1, crit: 150, critDmg: 120, apen: 60, fx: 1 },
  Fighter: { ad: 1.1, hp: 0.45, armor: 1.2, mr: 0.8, haste: 1.8, ls: 60, as: 40, apen: 40, fx: 1 },
  Tank: { hp: 0.7, armor: 2, mr: 2, haste: 2 },
  Mage: { ap: 2, hp: 0.35, haste: 2, mp: 0.1, mpen: 2, mpenPct: 150 },
  Assassin: { ad: 1.6, haste: 2.5, as: 20, leth: 2.2 },
  Support: { ap: 1.2, hp: 0.5, armor: 1.2, mr: 1.2, haste: 2.5 },
};
const BOOTS: Record<string, string> = { Marksman: '3006', Fighter: '3047', Tank: '3047', Mage: '3020', Assassin: '3158', Support: '3117' };
export function recommend(tags: string[]): string[] {
  const w: Record<string, number> = {};
  tags.slice(0, 2).forEach((t, i) => { for (const [k, v] of Object.entries(W[t] ?? {})) w[k] = (w[k] ?? 0) + v * (i ? 0.5 : 1); });
  const score = (it: ItemDef) =>
    (it.ad ?? 0) * (w.ad ?? 0) + (it.ap ?? 0) * (w.ap ?? 0) + (it.hp ?? 0) * (w.hp ?? 0) + (it.armor ?? 0) * (w.armor ?? 0) +
    (it.mr ?? 0) * (w.mr ?? 0) + (it.as ?? 0) * (w.as ?? 0) + (it.ls ?? 0) * (w.ls ?? 0) + (it.haste ?? 0) * (w.haste ?? 0) + (it.mp ?? 0) * (w.mp ?? 0) +
    (it.crit ?? 0) * (w.crit ?? 0) + (it.critDmg ?? 0) * (w.critDmg ?? 0) + (it.leth ?? 0) * (w.leth ?? 0) + (it.apen ?? 0) * (w.apen ?? 0) +
    (it.mpen ?? 0) * (w.mpen ?? 0) + (it.mpenPct ?? 0) * (w.mpenPct ?? 0) + (ITEM_FX[it.id] ? 40 * (w.fx ?? 0) : 0);
  const done = SHOP_ITEMS.filter((i) => !i.boots && (i.depth ?? 1) >= 3 && !(i.into?.length) && i.cost >= 2200);
  const best = done.sort((a, b) => score(b) / b.cost - score(a) / a.cost).slice(0, 12);
  const pick: ItemDef[] = [];
  for (const it of best) {
    // avoid stacking the same ability-haste-only profile twice: skip near-duplicates by name family
    if (pick.length < 5) pick.push(it);
  }
  const has = (id: string) => SHOP_ITEMS.some((i) => i.id === id);
  const boots = [BOOTS[tags[0]], '3020', '3047', '3009', '3006', '1001'].find((b) => b && has(b))!;
  return [boots, ...pick.map((p) => p.id)];
}

